// ==============================================================================
// PROJECT: CORTEX AI STUDIO
// FILE: types/ai.ts
// ROLE: Master TypeScript Contracts for AI State, Streaming & Telemetry
//
// 🎓 BEGINNER'S GUIDE TO FULL-STACK AI CONTRACTS:
//   In traditional web apps, data contracts describe database rows (like Users or Products).
//   In Full-Stack AI engineering, our contracts describe the lifecycle of reasoning:
//   1. Message: What the user asked and what the AI answered.
//   2. ThoughtTrace: Intermediate "thinking" tokens generated by reasoning models (like Gemini 2.0 Flash / o3-mini).
//   3. ToolCall: When the AI decides to execute an external tool (e.g., search web, query SQL, run code).
//   4. Artifact: Standalone generated assets (code files, charts, research reports) rendered in the canvas.
//   5. TelemetryMetrics: Crucial production stats (Time To First Token, tokens/sec, and API costs).
// ==============================================================================

export type ModelProvider = "gemini-2.0-flash" | "gpt-4o" | "claude-3-7-sonnet" | "simulator";

export type AgentRole = "supervisor" | "researcher" | "coder" | "fact-checker";

export interface ToolCallRecord {
  id: string;
  toolName: string;
  args: Record<string, unknown>;
  result?: unknown;
  status: "executing" | "completed" | "failed";
  timestamp: string;
}

export interface ThoughtTrace {
  step: number;
  agent: AgentRole;
  thought: string;
  timestamp: string;
}

export interface Artifact {
  id: string;
  title: string;
  type: "markdown" | "code" | "table" | "diagram";
  language?: string;
  content: string;
  createdAt: string;
}

export interface AIMessage {
  id: string;
  role: "user" | "assistant" | "system";
  content: string;
  createdAt: string;
  thoughts?: ThoughtTrace[];
  toolCalls?: ToolCallRecord[];
  artifact?: Artifact;
  modelUsed?: ModelProvider;
  telemetry?: {
    ttftMs: number;          // Time To First Token (milliseconds)
    durationMs: number;      // Total response duration
    promptTokens: number;
    completionTokens: number;
    tokensPerSecond: number;
    estimatedCostUsd: number;
  };
}

export interface ChatSession {
  id: string;
  title: string;
  createdAt: string;
  updatedAt: string;
  messages: AIMessage[];
}

export interface TelemetryState {
  activeModel: ModelProvider;
  activeAgent: AgentRole;
  isStreaming: boolean;
  latestTtftMs: number;
  averageTokensPerSec: number;
  totalTokensUsed: number;
  totalCostUsd: number;
}
